using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEditor;
using UnityEditor.SceneManagement;
using Object=UnityEngine.Object;
namespace Yamyam.OriginalTechTwelve.Placement.Editor {
    public static class PlacementCapture {
        const string Root="Assets/OriginalTechTwelve/PlacementV1",Asset="Assets/ThirdParty/LumaGrove/";
        const int Size=1080,Fps=60,Frames=720;static readonly int[] Preview={0,90,150,240,330,420,510,600,660,719};
        [Serializable] public class Job{public string output,fingerprint,mode;}
        [Serializable] public class Frame{public int frame;public bool objectsRevealed;public int actualTreeInstances,actualGrassInstances;}
        [Serializable] public class Trace{public string engine,mode,camera,fingerprint;public int fps=60;public string interpretation="CPU-authored rule illustration with licensed stylized assets; not Horizon GPU implementation, original density maps or a performance measurement";public PlacementState model;public List<Frame>frames=new List<Frame>();}
        static Job job;static PlacementLesson demo;static Trace trace;static int modeIndex,cameraIndex,index;static RenderTexture rt;static Texture2D pixels;
        static Material Mat(string name,Color color,Texture texture=null){string path=Root+"/Baked/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Yamyam/ArchitecturalSurface"));AssetDatabase.CreateAsset(m,path);}m.color=color;if(texture)m.mainTexture=texture;return m;}
        static GameObject Shape(string name,PrimitiveType type,Vector3 p,Vector3 scale,Material material){var g=GameObject.CreatePrimitive(type);g.name=name;g.transform.position=p;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=material;Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
        static GameObject Plant(string file,string name,float height,Material material){
            var source=AssetDatabase.LoadAssetAtPath<GameObject>(Asset+"Meshes/"+file);if(!source)throw new Exception("Missing licensed LumaGrove mesh: "+file);var g=(GameObject)PrefabUtility.InstantiatePrefab(source);g.name=name;var rr=g.GetComponentsInChildren<Renderer>();if(rr.Length==0)throw new Exception("Mesh renderer absent");var bounds=rr[0].bounds;foreach(var r in rr){bounds.Encapsulate(r.bounds);r.sharedMaterial=material;}g.transform.localScale=Vector3.one*(height/bounds.size.y);return g;
        }
        static Camera View(string name,Vector3 p,bool top){var c=new GameObject(name).AddComponent<Camera>();c.enabled=false;c.aspect=1;c.transform.position=p;c.transform.LookAt(Vector3.zero);c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=Color.black;c.fieldOfView=52;c.nearClipPlane=.1f;c.farClipPlane=80;c.orthographic=top;c.orthographicSize=11;return c;}
        static Mesh Terrain(){var mesh=new Mesh{name="Synthetic placement terrain"};const int side=41;var vertices=new Vector3[side*side];var triangles=new List<int>();for(int z=0;z<side;z++)for(int x=0;x<side;x++){float wx=(x/(float)(side-1)-.5f)*21,wz=(z/(float)(side-1)-.5f)*21;int k=z*side+x;vertices[k]=new Vector3(wx,PlacementModel.Height(wx,wz)-.04f,wz);if(x+1<side&&z+1<side)triangles.AddRange(new[]{k,k+side,k+1,k+1,k+side,k+side+1});}mesh.vertices=vertices;mesh.triangles=triangles.ToArray();mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,Root+"/Baked/terrain-"+modeIndex+".asset");return mesh;}
        public static void Run(){try{var args=Environment.GetCommandLineArgs();int j=Array.IndexOf(args,"-ot12Job");if(j<0)throw new Exception("Exact job required");job=JsonUtility.FromJson<Job>(File.ReadAllText(args[j+1]));if(job.mode!="pilot"&&job.mode!="full")throw new Exception("Invalid capture mode");Directory.CreateDirectory(job.output);if(Directory.EnumerateFiles(job.output,"*",SearchOption.AllDirectories).Any())throw new Exception("Preserve prior output");Directory.CreateDirectory(Root+"/Baked");Directory.CreateDirectory(Root+"/Scenes");modeIndex=0;Prepare();EditorApplication.update+=Tick;}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
        static void Prepare(){
            GraphicsSettings.defaultRenderPipeline=null;QualitySettings.renderPipeline=null;QualitySettings.antiAliasing=4;var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.skybox=null;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=Color.white;
            var state=PlacementModel.Build(PlacementModel.Modes[modeIndex]);var terrain=new GameObject("Same synthetic terrain");terrain.AddComponent<MeshFilter>().sharedMesh=Terrain();terrain.AddComponent<MeshRenderer>().sharedMaterial=Mat("ground",new Color(.1f,.17f,.1f));
            var brown=Mat("artist road map",new Color(.28f,.21f,.14f));for(int n=-10;n<10;n++)Shape("Authored road mask",PrimitiveType.Cube,new Vector3(0,PlacementModel.Height(0,n+.5f),n+.5f),new Vector3(3.2f,.035f,1),brown);
            var water=Mat("artist water map",new Color(.1f,.28f,.36f));for(int x=3;x<10;x++)for(int z=3;z<10;z++)Shape("Authored water mask",PrimitiveType.Cube,new Vector3(x+.5f,PlacementModel.Height(x+.5f,z+.5f),z+.5f),new Vector3(1,.04f,1),water);
            var texture=AssetDatabase.LoadAssetAtPath<Texture2D>(Asset+"Textures/EA04_LPNP-Artefacts_Colorsheet_v1.png");if(!texture)throw new Exception("Palette texture absent");var material=Mat("licensed foliage palette",Color.white,texture);var trees=new List<Transform>();var dots=new List<Transform>();
            foreach(var point in state.points){var tree=Plant("EA04_Trees_Cuboids_01a.fbx","Candidate tree "+point.id,2.4f*point.scale,material);tree.transform.position=new Vector3(point.x,point.y,point.z);tree.transform.rotation=(state.terrainAligned?Quaternion.FromToRotation(Vector3.up,new Vector3(point.normalX,point.normalY,point.normalZ)):Quaternion.identity)*Quaternion.Euler(0,point.yaw,0);trees.Add(tree.transform);dots.Add(Shape("Candidate "+point.id,PrimitiveType.Sphere,new Vector3(point.x,PlacementModel.Height(point.x,point.z)+.1f,point.z),Vector3.one*.22f,Mat(point.accepted?"accepted candidate":"rejected candidate",point.accepted?new Color(.45f,.9f,.78f):new Color(.94f,.45f,.42f))).transform);}
            var grass=new List<Transform>();for(int x=-9;x<10;x++)for(int z=-9;z<10;z++)if(PlacementModel.GrassAllowed(x,z)){var g=Plant("EA04_Grass_Stick_01a.fbx","Second layer grass",.48f,material);g.transform.position=new Vector3(x,PlacementModel.Height(x,z),z);grass.Add(g.transform);}
            demo=new GameObject("Artist maps to candidate placement illustration").AddComponent<PlacementLesson>();demo.mode=state.mode;demo.current=state;demo.trees=trees.ToArray();demo.dots=dots.ToArray();demo.grass=grass.ToArray();demo.forestView=View("Forest view",new Vector3(7,12,-17),false);demo.mapView=View("Placement map view",new Vector3(0,25,0),true);demo.Apply(0);demo.livePlayback=true;demo.forestView.enabled=true;EditorSceneManager.SaveScene(scene,Root+"/Scenes/"+state.mode+".unity");demo.livePlayback=false;demo.forestView.enabled=false;AssetDatabase.SaveAssets();
            if(rt)Object.DestroyImmediate(rt);if(pixels)Object.DestroyImmediate(pixels);rt=new RenderTexture(Size,Size,24,RenderTextureFormat.ARGB32){antiAliasing=4};rt.Create();pixels=new Texture2D(Size,Size,TextureFormat.RGB24,false);cameraIndex=0;BeginCamera();
        }
        static void BeginCamera(){index=0;trace=new Trace{engine=Application.unityVersion,mode=demo.mode,camera=cameraIndex==0?"forest":"map",fingerprint=job.fingerprint,model=demo.current};Directory.CreateDirectory(Path.Combine(job.output,demo.mode,trace.camera));}
        static void Tick(){try{int f=job.mode=="full"?index:Preview[index];demo.Apply(f/(float)Fps);var camera=cameraIndex==0?demo.forestView:demo.mapView;camera.targetTexture=rt;camera.Render();var previous=RenderTexture.active;RenderTexture.active=rt;pixels.ReadPixels(new Rect(0,0,Size,Size),0,0);pixels.Apply(false);RenderTexture.active=previous;trace.frames.Add(new Frame{frame=f,objectsRevealed=f>=180,actualTreeInstances=demo.trees.Count(x=>x.gameObject.activeSelf),actualGrassInstances=demo.grass.Count(x=>x.gameObject.activeSelf)});File.WriteAllBytes(Path.Combine(job.output,demo.mode,trace.camera,$"{f:D5}.png"),pixels.EncodeToPNG());if(++index<(job.mode=="full"?Frames:Preview.Length))return;File.WriteAllText(Path.Combine(job.output,demo.mode,trace.camera,"trace.json"),JsonUtility.ToJson(trace,true));if(cameraIndex++==0){BeginCamera();return;}if(++modeIndex<PlacementModel.Modes.Length){Prepare();return;}File.WriteAllText(Path.Combine(job.output,"complete.json"),"{\"fingerprint\":\""+job.fingerprint+"\",\"modes\":5,\"camerasPerMode\":2,\"framesPerCamera\":"+(job.mode=="full"?Frames:Preview.Length)+",\"actualUnityCapture\":true}");EditorApplication.update-=Tick;EditorApplication.Exit(0);}catch(Exception e){EditorApplication.update-=Tick;Debug.LogException(e);EditorApplication.Exit(1);}}
    }
}
